def coalesce(intervals):
    items = []
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be an iterable of integer pairs") from exc
    for interval in iterator:
        try:
            pair = tuple(interval)
        except TypeError as exc:
            raise ValueError("each interval must be a pair of integers") from exc
        if len(pair) != 2:
            raise ValueError("each interval must be a pair of integers")
        start, end = pair
        if (type(start) is not int or type(end) is not int or start >= end):
            raise ValueError("interval endpoints must be integers with start < end")
        items.append((start, end))
    items.sort()
    merged = []
    for start, end in items:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged
